/**
 * Сравнивает заданную дату/время + задержку с текущим временем,
 * используя данные из входящего массива 'items' (стандарт n8n).
 */
function compareTimeWithDelay() {

    // =================================================================
    // 🔥 ДОСТУП К ДАННЫМ, АДАПТИРОВАННЫЙ ДЛЯ N8N 🔥
    // N8n передает данные в глобальную переменную 'items'.
    // Мы берем первый элемент (items[0].json) и ищем в нем нашу структуру.
    // =================================================================

    // Входящая структура данных: [ { "data": [ { "time": "...", "delay": "..." } ] } ]

    const inputItem = items[0] ? items[0].json : null;

    // Получаем массив 'data'
    const dataArray = inputItem && inputItem.data && Array.isArray(inputItem.data) ? inputItem.data : [];

    // Получаем первый элемент из массива 'data'
    const dataObject = dataArray.length > 0 ? dataArray[0] : null;

    // Извлекаем строку даты/времени из 'time'.
    const dateTimeString = dataObject && typeof dataObject.time === 'string' ? dataObject.time : ''; 

    // Извлекаем значение задержки из 'delay'.
    const delayMinutes = dataObject && (typeof dataObject.delay === 'string' || typeof dataObject.delay === 'number') ? dataObject.delay : 0;

    // -----------------------------------------------------------------

    // --- Вспомогательная функция для возврата ошибки в требуемом формате ---
    // N8n ожидает массив объектов, где каждый объект имеет ключ 'json'
    const returnError = (errorMessage) => {
        console.log(`Ошибка: ${errorMessage}. Получено: ${dateTimeString} | ${delayMinutes}`);
        // Возвращаем объект, обернутый в 'json'
        return [{ json: { status: 'down', error_message: errorMessage } }];
    };

    // --- ПРОВЕРКА И ПАРСИНГ ---

    // Проверка формата даты (ДД.ММ.ГГГГ-ЧЧ:ММ)
    if (dateTimeString === '' || !dateTimeString.includes('-') || !dateTimeString.includes('.')) {
        return returnError(`Неверный формат даты/времени. Ожидается ДД.ММ.ГГГГ-ЧЧ:ММ.`); 
    }

    // Проверка задержки 
    const delay = Number(delayMinutes);
    if (isNaN(delay)) {
        return returnError('Значение задержки не является числом.');
    }

    // --- ВЫЧИСЛЕНИЯ ВРЕМЕНИ ---

    try {
        const [datePart, timePart] = dateTimeString.split('-');
        const [day, month, year] = datePart.split('.').map(Number);
        const [hour, minute] = timePart.split(':').map(Number); 

        // Создаем Date (месяц 0-индексирован)
        const targetDate = new Date(year, month - 1, day, hour, minute, 0, 0);

        if (isNaN(targetDate.getTime())) {
            return returnError(`Ошибка парсинга даты: ${dateTimeString}. Проверьте правильность ДД, ММ, ГГГГ.`);
        }

        // Вычисляем время с задержкой в миллисекундах
        const delayMilliseconds = delay * 60 * 1000;
        const targetTimeWithDelay = targetDate.getTime() + delayMilliseconds;

        // Текущее время
        const currentTime = Date.now(); 

        // --- СРАВНЕНИЕ И ФОРМИРОВАНИЕ ВЫХОДА ---

        let status;
        if (targetTimeWithDelay > currentTime) {
            status = 'work'; // work = полученное время + задержка > текущего времени
        } else {
            status = 'down'; // down = полученное время + задержка <= текущего времени
        }

        // 🔥 Возвращаем результат, обернутый в 'json' (стандарт n8n) 🔥
        return [{ json: { status: status } }];

    } catch (e) {
        return returnError(`Непредвиденная ошибка в скрипте: ${e.message}`);
    }
}

// 🚀 ЯВНЫЙ ВОЗВРАТ РЕЗУЛЬТАТА
return compareTimeWithDelay();
